import{_ as n,q as a,s as e,J as s}from"./framework-4ff91fa4.js";const t={},i=s(`<h2 id="kotlin-是什么" tabindex="-1"><a class="header-anchor" href="#kotlin-是什么" aria-hidden="true">#</a> Kotlin 是什么</h2><p>Kotlin 是一门静态类型语言：编译器会在运行前检查类型。它可以用于 JVM、Android、JavaScript 和原生平台。本教程以 Kotlin/JVM 为主，先学语言，再接触工具与工程；Android 和多平台开发放在最后的延伸路线中。</p><p>不需要先学 Java。你需要熟悉文件、终端和基本的逻辑思考。已经会 Java、Python 或 JavaScript 的读者，可以直接从变量、空安全和集合开始。</p><h2 id="运行第一段程序" tabindex="-1"><a class="header-anchor" href="#运行第一段程序" aria-hidden="true">#</a> 运行第一段程序</h2><p>打开 <a href="https://play.kotlinlang.org/" target="_blank" rel="noopener noreferrer">Kotlin Playground</a>，选择 JVM，输入下面的代码并点击 Run。普通语法章节的完整 <code>main</code> 示例都可以这样运行。</p><div class="language-kotlin line-numbers-mode" data-ext="kt"><pre class="language-kotlin"><code><span class="token keyword">fun</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">val</span> language <span class="token operator">=</span> <span class="token string-literal singleline"><span class="token string">&quot;Kotlin&quot;</span></span>
    <span class="token function">println</span><span class="token punctuation">(</span><span class="token string-literal singleline"><span class="token string">&quot;你好，</span><span class="token interpolation"><span class="token interpolation-punctuation punctuation">$</span><span class="token expression">language</span></span><span class="token string">！&quot;</span></span><span class="token punctuation">)</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出为 <code>你好，Kotlin！</code>。<code>fun</code> 声明函数，<code>main</code> 是入口，<code>println</code> 输出并换行。语句通常不需要分号。</p><h2 id="建议的学习方式" tabindex="-1"><a class="header-anchor" href="#建议的学习方式" aria-hidden="true">#</a> 建议的学习方式</h2><p>先按顺序完成基础、函数和面向对象，再学习集合与泛型，最后进入协程和工程。每章先预测输出，再运行代码，最后完成练习。不要只复制示例：修改一个条件，观察行为变化。</p><p>本教程覆盖常用语法与关键进阶主题。标准库全部 API、编译器实验功能与各平台框架仍应查询官方文档；本教程不会把框架功能混称为语言语法。</p><h2 id="动手练习" tabindex="-1"><a class="header-anchor" href="#动手练习" aria-hidden="true">#</a> 动手练习</h2><p>把问候语改成自己的名字，输出两行文字。</p><details><summary>查看参考思路</summary><p>在 main 中分别调用两次 println；字符串使用双引号。</p></details><h2 id="延伸阅读" tabindex="-1"><a class="header-anchor" href="#延伸阅读" aria-hidden="true">#</a> 延伸阅读</h2><p><a href="https://kotlinlang.org/docs/getting-started.html" target="_blank" rel="noopener noreferrer">Kotlin 官方文档：getting-started</a>。本章为原创中文学习笔记，示例以 Kotlin/JVM 为主；使用扩展库的章节需先配置依赖。</p>`,15),o=[i];function r(l,p){return a(),e("div",null,o)}const d=n(t,[["render",r],["__file","getting-started.html.vue"]]);export{d as default};
